import type { PlatformsType } from '@wix/cli-app-installer';
import { getSiteRedirectUrl, getAppPreviewUrl } from '@wix/cli-app-installer';
import type { PlatformLinkType } from '@wix/cli-plugin-core';

export const DEFAULT_PLATFORM_LABELS: Record<PlatformLinkType, string> = {
  site: 'Site',
  dashboard: 'Dashboard',
  editor: 'Editor',
};

export function getSiteDashboardUrl(siteId: string, overrideId: string) {
  return `https://manage.wix.com/dashboard/${siteId}?apps-override=${overrideId}`;
}

export function getSiteEditorUrl(siteId: string) {
  return `https://vibe.wix.com/projects/${siteId}`;
}

interface RedirectOptions {
  platform: PlatformsType;
  appId: string;
  versionOverrideId: string;
  siteId?: string;
}

export const createRedirectLink = ({ siteId, ...options }: RedirectOptions) => {
  if (siteId != null) {
    return getSiteRedirectUrl({ ...options, siteId });
  }

  return getAppPreviewUrl(options);
};
